"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass, replace
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError


@dataclass(frozen=True)
class Policy:
    max_size: int | None = None
    max_age: int | None = None  # seconds
    naming: str = "numbered"
    offset: int = 0  # minutes
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _size(v):
    if v == "off":
        return None
    m = re.fullmatch(r"([0-9]+)([KMGkmg]?)", v)
    if not m:
        raise ValueError
    return int(m[1]) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m[2].lower()]


def _age(v):
    if v == "off":
        return None
    m = re.fullmatch(r"([0-9]+)([mhd])", v)
    if not m:
        raise ValueError
    return int(m[1]) * {"m": 60, "h": 3600, "d": 86400}[m[2]]


def _naming(v):
    if v not in ("numbered", "dated"):
        raise ValueError
    return v


def _offset(v):
    m = re.fullmatch(r"([+-])([0-9]{2}):([0-9]{2})", v)
    if not m or int(m[2]) > 23 or int(m[3]) > 59:
        raise ValueError
    minutes = int(m[2]) * 60 + int(m[3])
    return -minutes if m[1] == "-" else minutes


def _count(minimum):
    def parse(v):
        if not re.fullmatch(r"[0-9]+", v) or int(v) < minimum:
            raise ValueError
        return int(v)

    return parse


def _keep_days(v):
    return None if v == "off" else _count(1)(v)


PARSERS = {
    "max_size": _size,
    "max_age": _age,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _keep_days,
}


class Rules:
    """The policy of every stream."""

    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections

    def names(self) -> set:
        return set(self.sections)

    def get(self, name: str) -> Policy:
        values = dict(self.defaults)
        values.update(self.sections.get(name, {}))
        return replace(Policy(), **values)


def load(path: Path) -> Rules:
    if not path.exists():
        return Rules({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults, sections = {}, {}
    seen_defaults = False
    current = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                raise _bad(f"bad section line: {line}")
            title = line[1:-1]
            if title == "defaults":
                if seen_defaults:
                    raise _bad("section [defaults] twice")
                seen_defaults = True
                current = defaults
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    raise _bad(f"section {name} twice")
                current = sections[name] = {}
            else:
                raise _bad(f"unknown section: {line}")
            continue
        if current is None or "=" not in line:
            raise _bad(f"bad line: {line}")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in PARSERS:
            raise _bad(f"unknown key: {key}")
        if key in current:
            raise _bad(f"key twice: {key}")
        try:
            current[key] = PARSERS[key](value)
        except ValueError:
            raise _bad(f"bad value for {key}: {value}") from None
    return Rules(defaults, sections)
