"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

ISO = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}([.,][0-9]+)?)?(Z|[+-][0-9]{2}(:?[0-9]{2})?)")
LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}")
NUM = r"[1-9][0-9]*"
DAY = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.(" + NUM + r"))?")


def parse_iso(text):
    """An ISO 8601 time with Z or an offset, or None."""
    if not ISO.fullmatch(text):
        return None
    try:
        t = datetime.fromisoformat(text.replace(",", "."))
    except ValueError:
        return None
    return t if t.tzinfo is not None else None


def parse_state_time(value):
    """A time of data.md, section 2, or None."""
    if not isinstance(value, str):
        return None
    if LEGACY.fullmatch(value):
        try:
            return datetime.fromisoformat(value).replace(tzinfo=timezone.utc)
        except ValueError:
            return None
    return parse_iso(value)


class Arc:
    def __init__(self, old, compressed, key, base, time):
        self.old = old  # file name before the run, None for the new archive
        self.compressed = compressed
        self.key = key
        self.base = base  # dated: name without .gz
        self.time = time  # as stored in state.json
        self.final_compressed = compressed
        self.final = old


def find_archives(names, name, naming):
    prefix = f"{name}.log."
    found = []
    for fn in names:
        if not fn.startswith(prefix):
            continue
        rest = fn[len(prefix):]
        gz = rest.endswith(".gz")
        if gz:
            rest = rest[:-3]
        if naming == "numbered":
            if not re.fullmatch(NUM, rest):
                continue
            key = (int(rest),)
        else:
            m = DAY.fullmatch(rest)
            if not m:
                continue
            try:
                day = date.fromisoformat(m[1])
            except ValueError:
                continue
            k = int(m[2]) if m[2] else 1
            if m[2] and k < 2:
                continue
            key = (day, k)
        found.append(Arc(fn, gz, key, prefix + rest, None))
    places = {}
    for a in found:
        if a.key in places:
            raise DataError("archives", f"{a.old} and {places[a.key]} are in the same place")
        places[a.key] = a.old
    found.sort(key=lambda a: a.key)
    return found


def _check_state(doc, existing):
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        bad = DataError("state", f"state.json: bad entry {name}")
        if "opened" in entry and parse_state_time(entry["opened"]) is None:
            raise bad
        if "rotations" in entry:
            r = entry["rotations"]
            if not isinstance(r, int) or isinstance(r, bool) or r < 0:
                raise bad
        if "archives" in entry:
            arcs = entry["archives"]
            if not isinstance(arcs, dict):
                raise bad
            for v in arcs.values():
                if parse_state_time(v) is None:
                    raise bad


def _first_line_time(path):
    with path.open("rb") as f:
        line = f.readline()
    text = line.decode("utf-8", errors="replace").rstrip("\r\n")
    if " " not in text:
        return None
    return parse_iso(text.split(" ", 1)[0])


def run(ctx, requested, dry_run, force):
    rules = policy.load(ctx.policy_path)
    doc = ctx.state
    logs = streams.logs_dir(ctx.data)
    existing = set(streams.active(ctx.data)) | rules.names()
    _check_state(doc, existing)
    if requested:
        todo = sorted(set(requested))
        for n in todo:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        todo = sorted(existing)

    filenames = sorted(p.name for p in logs.iterdir() if p.is_file()) if logs.is_dir() else []
    plans = []
    for name in todo:
        pol = rules.get(name)
        entry = doc["streams"].get(name, {})
        plans.append((name, pol, entry, find_archives(filenames, name, pol.naming)))

    now = ctx.now
    out = []
    n_rot = n_rem = n_comp = 0
    reads = {}  # file name -> bytes, for files that change
    unlink, writes = [], {}
    new_entries = {}
    for name, pol, entry, arcs in plans:
        log = streams.log_path(ctx.data, name)
        stored = entry.get("archives", {})
        for a in arcs:
            a.time = stored.get(a.old)
        opened = parse_state_time(entry["opened"]) if "opened" in entry else None
        if opened is None and log.is_file():
            opened = _first_line_time(log)
        size = log.stat().st_size if log.is_file() else 0
        if not log.is_file():
            why = "no log"
        elif size == 0:
            why = "empty"
        elif force:
            why = "forced"
        elif pol.max_size is not None and size >= pol.max_size:
            why = "size"
        elif pol.max_age is not None and opened is not None and now - opened >= timedelta(seconds=pol.max_age):
            why = "age"
        else:
            why = "not due"
        rotated = why in ("forced", "size", "age")
        out.append(f"{name}: " + (f"rotate ({why})" if rotated else why))

        if rotated:
            if pol.naming == "numbered":
                new = Arc(None, False, (0,), None, dates.stamp(now))
                arcs.insert(0, new)
            else:
                tz = timezone(timedelta(minutes=pol.offset))
                day = now.astimezone(tz).date()
                ks = [a.key[1] for a in arcs if a.key[0] == day]
                base = f"{name}.log.{day.isoformat()}" + (f".{max(ks) + 1}" if ks else "")
                k = max(ks) + 1 if ks else 1
                new = Arc(None, False, (day, k), base, dates.stamp(now))
                arcs.append(new)
                arcs.sort(key=lambda a: a.key)
            n_rot += 1

        keep_days = timedelta(days=pol.keep_days) if pol.keep_days is not None else None
        kept, removed = [], []
        for i, a in enumerate(arcs, 1):
            t = parse_state_time(a.time) if a.time is not None else None
            if i > pol.keep or (keep_days is not None and t is not None and now - t >= keep_days):
                removed.append(a)
            else:
                kept.append(a)
        n_rem += len(removed)

        lines = []
        for i, a in enumerate(kept, 1):
            if i > pol.compress_after and not a.compressed:
                a.final_compressed = True
                n_comp += 1
            if pol.naming == "numbered":
                a.final = f"{name}.log.{i}"
            else:
                a.final = a.base
            if a.final_compressed:
                a.final += ".gz"
            if a.old is None:
                lines.append(f"  new {a.final}")
            elif a.final != a.old:
                lines.append(f"  {a.final} <- {a.old}")
            else:
                lines.append(f"  {a.final}")
        out.extend(lines)
        out.extend(f"  remove {a.old}" for a in removed)

        for a in removed:
            unlink.append(a.old)
        for a in kept:
            if a.old is None:
                data = log.read_bytes()
                writes[a.final] = gzip.compress(data, mtime=0) if a.final_compressed else data
            elif a.final != a.old:
                data = (logs / a.old).read_bytes()
                if a.final_compressed and not a.compressed:
                    data = gzip.compress(data, mtime=0)
                unlink.append(a.old)
                writes[a.final] = data
        if rotated:
            writes_active = True
            unlink_active = log
            reads[name] = unlink_active

        ne = {}
        if rotated:
            ne["opened"] = dates.stamp(now)
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = {a.final: a.time for a in kept if a.time is not None}
        new_entries[name] = ne

    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    for fn in unlink:
        (logs / fn).unlink()
    for fn, data in writes.items():
        (logs / fn).write_bytes(data)
    for log in reads.values():
        log.write_bytes(b"")
    doc["streams"].update(new_entries)
    state.save(ctx.state_path, doc)
    return out
